import json

def read_value_field(record):
    try:
        return json.load(record)['value']
    except json.JSONDecodeError:
        print("Invalid JSON data.")
        return None

sample_record = """
{
  "record": {
    "name": "John Doe",
    "age": 30,
    "city": "New York"
  },
  "address": {
    "street": "123 Main St",
    "city": "Anytown"
  }
}
"""

print(read_value_field(sample_record))

